    }
  </TouchableOpacity>
)

// ── File card ────────────────────────────────────────────
const FileCard = ({
  file,
  onDownload,
  onDelete,
}: {
  file:     UploadedFile
  onDownload: (uri: string) => void
  onDelete:   (fileId: number) => void
}) => {
  const [downloading, setDownloading] = useState(false)
  const [deleting,    setDeleting]    = useState(false)

  const handleDownload = async () => {
    if (downloading) return
    setDownloading(true)
    try {
      const res = await arkzenFetch(`${BACKEND_URL}/api/upload-test/files/${file.id}/url`)
      const d   = await res.json()
      const uri = d.url
      onDownload(uri)
    } catch {} finally { setDownloading(false) }
  }

  const handleDelete = async () => {
    if (!window.confirm('Delete this file?')) return
    if (deleting) return
    setDeleting(true)
    try {
      await arkzenFetch(`${BACKEND_URL}/api/upload-test/files/${file.id}`, {
        method: 'DELETE',
