  const [progress,  setProgress]    = useState(0)
  const [dropping,  setDropping]    = useState(false)
  const [dropText,  setDropText]    = useState('Tap or drop files to upload')
  const [error,     setError]       = useState<string | null>(null)

  const loadFiles = useCallback(async (userId?: number) => {
    try {
      const res = await arkzenFetch(`${BACKEND_URL}/api/upload-test/files${userId ? `?user=${userId}` : ''}`)
      const d   = await res.json()
      if (!res.ok) throw new Error(d.message ?? 'Load failed')
      const items = Array.isArray(d.data) ? d.data : Array.isArray(d) ? d : []
      setFiles(items.filter(f => f.stored_name !== null))
      setImageSrcs(items.filter(f => f.is_image && f.stored_name != null).map(f => `${BACKEND_URL}${f.disk_path}`))
    } catch (e) {
      console.error('[upload-test] Failed to load files:', e)
    }
  }, [])

  useEffect(() => { if (user) loadFiles(user.id) }, [user])

  // ──────────────────────────────────────────────
  // Drop target handlers
  // ──────────────────────────────────────────────

  const handleDragOver = (e: any) => {
    e.preventDefault()
    setDropping(true)
    setDropText('Release to upload')
  }

  const handleDragLeave = () => {
    setDropping(false)
    setDropText('Tap or drop files to upload')
  }

  const handleDrop = async (e: any) => {
    e.preventDefault()
    setDropping(false)
    setDropText('Tap or drop files to upload')

    if (!e.dataTransfer.files.length) return
    const dt = e.dataTransfer
    await handleDropOrPick(dt.files as FileList)
  }

  // ──────────────────────────────────────────────
  // Picker + drag handlers
  // ──────────────────────────────────────────────

  const handlePick = async (picked: FileList) => {
    await handleDropOrPick(picked)
  }

  const handleDropOrPick = async (picked: FileList) => {
    if (!picked.length) return
    const total = picked.length
    let done  = 0
    let rejectCount = 0

    for (let i = 0; i < total; i++) {
      const f = picked[i]
      try {
        const url = await getSignedUrl(f.name, f.size, f.type)
        if (!url) {
          rejectCount++
          continue
        }
        const res = await arkzenFetch(url, {
          method: 'PUT',
          body:   await f.arrayBuffer(),
          headers: { 'Content-Type': f.type },
        })
        if (!res.ok) throw new Error(`Upload failed (${res.status})`)
        done++
      } catch (err) {
        console.error('[upload-test] Upload error:', err)
        setError(`${err instanceof Error ? err.message : 'Upload failed'}. ${done} of ${total - rejectCount} saved.`)
      }
    }
    if (done > 0) {
      toast(`${done} file${done === 1 ? '' : 's'} saved`, 'success')
      loadFiles(user?.id)
    }
  }

  // ──────────────────────────────────────────────
  // Individual file actions
