    try {
      const res = await arkzenFetch(`${BACKEND_URL}/api/upload-test/files/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error(await res.text())
      toast('Deleted', 'info')
      loadFiles(user?.id)
    } catch (e) {
      console.error('[upload-test] Delete failed:', e)
      toast(e instanceof Error ? e.message : 'Delete failed', 'error')
    }
  }

  const handleDownload = async (storedName: string, mimeType: string, sizeBytes: number) => {
    try {
      const url = await getSignedUrl(storedName, sizeBytes, mimeType)
      if (!url) throw new Error('Could not get download URL')
      const res = await fetch(url)
      if (!res.ok) throw new Error(`Request failed (${res.status})`)
      const blob = await res.blob()
