import React, { useState, useEffect } from 'react'
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  ActivityIndicator,
  ScrollView,
} from 'react-native'
import { arkzenFetch } from '@/arkzen/core/stores/authStore'

const BACKEND_URL = process.env.ARKZEN_BACKEND_URL ?? 'http://localhost:8000'
/* @arkzen:import:rn:end */

interface ProbeResult {
  id:           number
  source:       string
  probe:        string
  payload:      string | null
  result:       string
  ok:           boolean
  created_at:   string
}

type ApiStatus = 'idle' | 'running' | 'done' | 'failed'

// ── Reusable input field ───────────────────────────────────────
const Field = ({
  placeholder,
  value,
  onChangeText,
  secureTextEntry = false,
}: {
  placeholder:    string
  value:          string
  onChangeText:   (v: string) => void
  secureTextEntry?: boolean
}) => (
  <TextInput
    className="bg-neutral-50 border border-neutral-200 rounded-xl px-4 py-3 text-sm text-neutral-900"
    placeholder={placeholder}
    placeholderTextColor="#a3a3a3"
    value={value}
    onChangeText={onChangeText}
    secureTextEntry={secureTextEntry}
    autoCapitalize="none"
    autoCorrect={false}
  />
)

// ── Primary button ─────────────────────────────────────────────
const PrimaryBtn = ({
  label,
  onPress,
  loading = false,
}: {
  label:    string
  onPress:  () => void
  loading?: boolean
}) => (
  <TouchableOpacity
    onPress={onPress}
    disabled={loading}
    activeOpacity={0.8}
    className={`py-3.5 rounded-2xl items-center ${loading ? 'bg-neutral-300' : 'bg-neutral-900'}`}
  >
    {loading
      ? <ActivityIndicator size="small" color="#fff" />
      : <Text className="text-white text-sm font-semibold">{label}</Text>
    }
  </TouchableOpacity>
)

// ── Error box ──────────────────────────────────────────────────
const ErrorBox = ({ message }: { message: string }) => (
  <View className="p-3 bg-red-50 border border-red-100 rounded-xl">
    <Text className="text-xs text-red-600">{message}</Text>
  </View>
)

// ── Probe card ─────────────────────────────────────────────────
const ProbeCard = ({
  probe,
  result,
  ok,
  isLoading = false,
  onRun,
}: {
  probe:     string
  result:    string | null
  ok:        boolean | null
  isLoading: boolean
  onRun:     () => void
}) => {
  const statusStyle = result == null
    ? { bg: 'bg-neutral-100', check: 'text-neutral-400', text: 'text-neutral-400' }
    : ok
      ? { bg: 'bg-green-50', check: 'text-green-700', text: 'text-green-700' }
      : { bg: 'bg-red-50', check: 'text-red-600', text: 'text-red-600' }

  return (
    <View className="bg-white rounded-2xl p-4 border border-neutral-100 mb-2 overflow-hidden">
      {/* Probe name */}
      <Text className="text-xs font-semibold text-neutral-400 uppercase tracking-wide mb-1">
        {probe.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase())}
      </Text>

      {/* Result checkmark card */}
      <View className={`rounded-lg p-4 items-center ${statusStyle.bg}`}>
        <Text className={`text-3xl mb-1 ${statusStyle.check}`}>{result == null ? '...' : (ok ? '✓' : '✗')}</Text>
        <Text className={`text-sm ${statusStyle.text}`}>{result == null ? 'Testing…' : ok ? 'Passed' : 'Failed'}</Text>
      </View>

      {/* Run button */}
      <PrimaryBtn
        label={isLoading ? 'Testing…' : 'Run'}
        onPress={onRun}
        loading={isLoading}
      />
    </View>
  )
}

// ── Result row ─────────────────────────────────────────────────
const ResultRow = ({ result }: { result: ProbeResult }) => {
  const kindStyle = result.ok
    ? { bg: 'bg-green-50', check: 'text-green-600', text: 'text-green-600' }
    : { bg: 'bg-red-50', check: 'text-red-600', text: 'text-red-600' }

  return (
    <View className="flex-row items-start gap-2 pb-3 border-b border-neutral-50 mb-1">
      {/* Kind badge */}
      <View className={`px-2 py-0.5 rounded-full ${kindStyle.bg}`}>
        <Text className={`text-xs font-medium ${kindStyle.text}`}>
          {result.ok ? '✅ OK' : '✗ FAIL'}
        </Text>
      </View>

      {/* Result body */}
      <View className="flex-1 min-w-0">
        <Text className="text-sm text-neutral-700 truncate" numberOfLines={1}>
          {result.probe}
        </Text>
        {result.payload && (
          <Text className="text-xs mt-0.5 text-neutral-400" numberOfLines={1}>
            · Payload: {result.payload.length > 30 ? result.payload.slice(0, 30) + '…' : result.payload}
          </Text>
        )}
        <Text className="text-xs mt-0.5 text-neutral-300 shrink-0">
          {result.created_at?.slice(0, 19).replace('T', ' ')}
        </Text>
      </View>

      {/* Result code */}
      <View className="bg-neutral-100 rounded-xl px-2.5 py-1">
        <Text className="text-xs font-mono text-neutral-500 shrink-0">
          #{result.id}
        </Text>
      </View>
    </View>
  )
}

